Definition binvN (own' : mem -> Prop) (BX : list (Z * Z)) (M1 : mem) (model1 : Model) (LK1 : list fframe) (cr1 : credit) (Aw1 : list (Z * Z)) : Prop :=
  ri_inv HI (BX ++ LBX) FF LK1 cr1 Aw1 M1 (vml_of model1) /\ L5CA.amodel_ok Aw1 model1 /\ model_rt model model1 /\ incl Aw Aw1 /\ incl LK1 LK /\
  L5CA.astk ar M1 sp SCR /\ ek L ar LBX FF sp SCR WA M M1 /\ dk L ar LBX FF sp SCR M M1 /\ own' M1.
Definition n_memG (own' : mem -> Prop) (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z)) (st1 : PQMA.ast) (eso1 : list (Z * Z)) (qe1 : credit) (cr1 : credit) : Prop :=
  binvN own' (PQMA.aown st1 ++ eso1) M1 model1 LK1 cr1 Aw1
  /\ adaptor_at M1 oa ov st1 /\ accA M1 oa PQMA.ASIZE /\ PQMA.adaptor_ok st1 /\ EVIS M1 ov /\ PMSTA.base_okA RSEGS AD M1
  /\ PMSP.credit_keep cr cr1 (PM.credit_add (POT sa) QE) (PM.credit_add (POT st1) qe1) /\ (PMSP.credit_le (PM.credit_add (POT st1) qe1) cr1 /\ 0 <= fst qe1 /\ 0 <= snd qe1).   (* [comment removed for export] *)
Definition n_mem := n_memG own.
Definition n_memE := n_memG (fun _ => True).

