Lemma n_kstr own' M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 o x :
  n_memG own' M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> 24 <= o -> o + 24 <= 72 -> kstr_at M1 (oa + o) x -> incl (PM.vs_own x) (PQMA.aown st1) ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  match x with
  | PM.VShort n => L5.u8_at RSEGS MV (oa + o) (2 * n) /\ 0 <= 2 * n <= 44 /\ Z.testbit (2 * n) 0 = false /\ 0 <= n <= 22
  | PM.VLong c n p => L5.u8_at RSEGS MV (oa + o) ((c + 1) mod 256) /\ 0 <= (c + 1) mod 256 <= 255 /\ Z.testbit ((c + 1) mod 256) 0 = true
      /\ L5.u64_at RSEGS MV (oa + o + 8) n /\ 0 <= n <= 2147483648 /\ L5.u64_at RSEGS MV (oa + o + 16) p /\ 4096 <= p <= 140737488355328
      /\ In (p, c) (PQMA.aown st1) /\ 0 <= n < c /\ 26 <= c <= 2147483648 /\ accA M1 p c /\ L5.defined M1 p c
