(* [comment removed for export] *)
Lemma n_stk own' M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 :
  n_memG own' M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  (forall a n0, sp - SCR <= a -> a + n0 <= sp -> avis (ahid Aw1 model1) a n0)
  /\ L5.writable RSEGS MV (sp - SCR) SCR
  /\ (L5.img_clear MV 65536 1409024 /\ L5.u64_at RSEGS MV 1440376 2147450880 /\ L5.u32_at RSEGS MV 1440384 1)
  /\ own' M1.
Proof using All.
