Lemma n_call_lvpush M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (fx1 : FPState) R1 (pcp ra off1 off2 t k : Z) :
  PQSAXL.lvpush_spec RSEGS AD L ar HI pcp ->
  n_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (oa + 72) -> getr R1 (reg 11) = Z_to_bv 64 (spc + off1) -> getr R1 (reg 12) = Z_to_bv 64 (spc + off2) ->
  0 <= off1 -> off1 + 4 <= FR -> off1 mod 4 = 0 -> 0 <= off2 -> off2 + 4 <= FR -> off2 mod 4 = 0 ->
  L5.u32_at RSEGS M1 (spc + off1) t -> (t = 0 \/ t = 1) -> L5.u32_at RSEGS M1 (spc + off2) k -> (k = 1 \/ k = 2) ->
  PQMA.nlv st1 <= PQMA.MAX_DEPTH ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 b' k' cr3,
      regs_preserved R1 R2 ->
      n_mem M3 model3 LK3 Aw3 (PQMA.AST (PQMA.a_lv st1 ++ [PQMA.AL t k (PQSAXL.lvl_eo k)]) b' k' (PQMA.a_key st1) (PQMA.a_kg st1) (PQMA.a_kb st1) (PQMA.a_kbg st1)) eso1 qe1 cr3 ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      L5CA.ahpres L ar (((PM.vs_own (PQMA.a_key st1) ++ PM.vs_own (PQMA.a_kb st1)) ++ eso1) ++ LBX) FF spc (PMSPA.pm_scr 0) [(oa + 72, 24)] M1 M3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pcp M1 model1) K.
