(* [comment removed for export] *)
Lemma n_ret own' M5 model5 LK5 Aw5 st5 eso5 qe5 cr5 (fx5 : FPState) R5 (pc5 : Z) (Wi : bv 32) :
  n_memG own' M5 model5 LK5 Aw5 st5 eso5 qe5 cr5 ->
  fetch_word RSEGS (Z_to_bv 64 pc5) = Some Wi -> is_ecall Wi = false -> decode_any Wi = Some (Jalr 0 1 0, 4%Z) ->
  getr R5 (reg 1) = getr R (reg 1) ->
  (forall model6,
      adaptor_at M5 oa ov st5 -> PQMA.adaptor_ok st5 ->
      L5CA.ahpres L ar LBX FF sp SCR WA M M5 ->
      PMSP.credit_keep cr cr5 (PM.credit_add (POT sa) QE) (PM.credit_add (POT st5) qe5) ->
      model_rt model model6 -> incl LK5 LK -> incl Aw Aw5 -> L5CA.amodel_ok Aw5 model6 ->
      ri_inv HI ((PQMA.aown st5 ++ eso5) ++ LBX) FF LK5 cr5 Aw5 M5 (vml_of model6) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 r M5 model6) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
