Lemma n_parts M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (M3 : mem) (Wl : list L5.range) :
  n_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> L5SAR.ek L ar ((PQMA.aown st1 ++ eso1) ++ LBX) FF sp SCR Wl M1 M3 -> PMKA.wapp Wl -> mem_grows M1 M3 ->
  (forall a n, oa <= a -> a + n <= oa + 96 -> (forall i, a <= i < a + n -> L5.outside Wl i) -> PMFA.agA M1 M3 a n)
  /\ (forall q m, In (q, m) (PQMA.aown st1) -> (forall i, q <= i < q + m -> L5.outside Wl i) -> PMFA.agA M1 M3 q m)
  /\ (forall q m, In (q, m) (PQMA.aown st1) -> PMFA.agsh M1 M3 q m /\ L5.defined M3 q m
                  /\ (forall i, q <= i < q + m -> L5.outside Wl i -> M3 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)))
  /\ L5.defined M3 oa 96.
Proof using All.
