(* [comment removed for export] *)
Lemma n_adv M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 lv0 c (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) :
  n_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> PQMA.a_lv st1 = lv0 ++ [c] ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (PQMA.a_lb st1 + 24 * (Z.of_nat (length lv0) + 1) - 16 <= i < PQMA.a_lb st1 + 24 * (Z.of_nat (length lv0) + 1) - 16 + 4)
             -> ~ (PQMA.a_lb st1 + 24 * (Z.of_nat (length lv0) + 1) - 8 <= i < PQMA.a_lb st1 + 24 * (Z.of_nat (length lv0) + 1) - 8 + 8)
             -> M2v (Z_to_bv 64 i) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 i)) ->
  L5.u32_at RSEGS M2v (PQMA.a_lb st1 + 24 * (Z.of_nat (length lv0) + 1) - 16) (PQMA.lv_eo (adv c)) ->
  (forall (M3 : mem) model3,
      n_mem M3 model3 LK1 Aw1 (PQAKT3N.set_lv st1 (lv0 ++ [adv c])) eso1 qe1 cr1 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc1 M1 model1) K.
