Let LYa := PMA.ly_as0 L C LY.
(* [comment removed for export] *)
Variables (FF : list fframe) (oa ov osk oec cat : Z).
Hypothesis AO : PMSPA.aobjA FF oa PQMA.ASIZE.
Hypothesis AOV : PMSPA.aobjA FF ov 56.
Hypothesis AOSK : PMSPA.aobjA FF osk 24.
Hypothesis AOEC : PMSPA.aobjA FF oec 16.
(* [comment removed for export] *)
Hypothesis OAL : 7036928 <= oa.

(* [comment removed for export] *)
Definition xinvG (M1 : mem) (kb1 : PM.vstr) (kbb1 : list Z) (en1 : NEM.enc) (k1 : NESK.sink) (b1 e1 : bool) : Prop :=
  NEM.kcontent RSEGS M1 (oa + PQMA.AOFF_KB) kb1 kbb1 /\ utf8_valid kbb1 = true
  /\ NEMA.enc_atA RSEGS AE L ar M1 ov osk en1 /\ NESKA.sink_atA RSEGS L ar (NESKA.PMEA L) M1 osk k1
  /\ NEMA.ec_stateA RSEGS AD M1 oec b1 cat /\ PQSTA.err_okA RSEGS AD AAD AQ M1 e1.

(* [comment removed for export] *)
Lemma xinv_ekG LBf LK1 cr1 Aw1 V1 sp scr (M1 M3 : mem) st1 kbb1 en1 k1 b1 e1 :
  ri_inv HI LBf FF LK1 cr1 Aw1 M1 V1 -> adaptor_at M1 oa ov st1 ->
  incl (PQMA.aown st1) LBf -> incl (NEM.enc_own en1) LBf -> incl (NESK.sink_own k1) LBf ->
  L5SAR.ek L ar LBf FF sp scr [] M1 M3 ->
  xinvG M1 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1 -> xinvG M3 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1.
Proof.
