(* [comment removed for export] *)
Lemma xinv_ekF LBf FFx sp scr (M1 M3 : mem) st1 kbb1 en1 k1 b1 e1 :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) -> (forall b0, In b0 LBf -> 0 <= fst b0 /\ fst b0 + snd b0 <= 2 ^ 47) ->
  PMSPA.aobjA FFx oa PQMA.ASIZE -> PMSPA.aobjA FFx ov 56 -> PMSPA.aobjA FFx osk 24 -> PMSPA.aobjA FFx oec 16 ->
  adaptor_at M1 oa ov st1 ->
  incl (PQMA.aown st1) LBf -> incl (NEM.enc_own en1) LBf -> incl (NESK.sink_own k1) LBf ->
  L5SAR.ek L ar LBf FFx sp scr [] M1 M3 ->
  xinvG M1 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1 -> xinvG M3 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1.
