(* [comment removed for export] *)
Lemma xinv_callG LBc LK1 cr1 Aw1 V1 sp scr (W' : list L5.range) (M1 M4 : mem) kb4 kbb4 en1 k1 b1 e1 :
  ri_inv HI LBc FF LK1 cr1 Aw1 M1 V1 -> incl (NEM.enc_own en1) LBc -> incl (NESK.sink_own k1) LBc ->
  (oa + PQMA.ASIZE <= ov \/ ov + 56 <= oa) -> (oa + PQMA.ASIZE <= osk \/ osk + 24 <= oa) -> (oa + PQMA.ASIZE <= oec \/ oec + 16 <= oa) ->
  (forall rr a, In rr W' -> L5.in_rng rr a -> oa <= a < oa + PQMA.ASIZE) -> PMKA.wapp W' ->
  L5CA.ahpres L ar LBc FF sp scr W' M1 M4 ->
  NEMA.enc_atA RSEGS AE L ar M1 ov osk en1 -> NESKA.sink_atA RSEGS L ar (NESKA.PMEA L) M1 osk k1 ->
  NEMA.ec_stateA RSEGS AD M1 oec b1 cat -> PQSTA.err_okA RSEGS AD AAD AQ M1 e1 ->
  NEM.kcontent RSEGS M4 (oa + PQMA.AOFF_KB) kb4 kbb4 -> utf8_valid kbb4 = true ->
  xinvG M4 kb4 kbb4 en1 k1 b1 e1.
