(* [comment removed for export] *)
Section SlotX.
Import PQAKS3N.
Local Ltac zl := L5FastLia.plia.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis ICok : aicpt_ok L ar IL SCFG HI.
Hypothesis ILY : as0_icpt_layout IL.
Let LYa := PMA.ly_as0 L C LY.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r oa ov osk oec : Z) (sa : PQMA.ast) (eso : list (Z * Z)) (QE : credit).
Hypothesis HH : ri_inv HI ((PQMA.aown sa ++ eso) ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis QENN : 0 <= fst QE /\ 0 <= snd QE.
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r PNVA.VIS_H.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM PNVA.VIS_H FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis AO : PMSPA.aobjA FF oa PQMA.ASIZE.
Hypothesis O8 : oa mod 8 = 0.
Hypothesis AOV : PMSPA.aobjA FF ov 56.
Hypothesis APT : oa + PQMA.ASIZE <= ov \/ ov + 56 <= oa.
Hypothesis AOSK : PMSPA.aobjA FF osk 24.
Hypothesis AOEC : PMSPA.aobjA FF oec 16.
Hypothesis AA : adaptor_at M oa ov sa.
Hypothesis OACC : accA M oa PQMA.ASIZE.
Hypothesis AOK : PQMA.adaptor_ok sa.
Hypothesis VIS : PQAKS3N.EVIS M ov.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
(* [comment removed for export] *)
Variable cat : Z.
Hypothesis APT2 : oa + PQMA.ASIZE <= osk \/ osk + 24 <= oa.
Hypothesis APT3 : oa + PQMA.ASIZE <= oec \/ oec + 16 <= oa.
Local Notation SCR := (PMSPA.pm_scr PNVA.VIS_H).
Local Notation WA := (NEMA.ae_WA AD oa ov osk oec).
Local Notation POT := (fun x => PMSPA.scA L (PQMA.pot_adaptor (PMSPA.HV L ar) x)).
Local Notation EPOT := (NECSA.pot_encA L ar (NESKA.PMEA L)).
Local Notation xinv := (xinvG L ar oa ov osk oec cat).
Local Notation "'SX' f" := (f L ar C IL HI LY HIok ICok ILY K R M model LBX FF LK Aw cr sp r oa ov osk oec sa eso QE HH QENN AM K0 ENT FRM FRS AO O8 AOV APT AOSK AOEC AA OACC AOK VIS BASE) (at level 10, f at level 9, only parsing).
Local Notation "'GX' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PNVA.VIS_H (PQMA.aown sa ++ eso) WA HH AM K0 ENT FRM FRS PQAKS3N.Hh3 (SX PQAKS3N.wappW)) (at level 10, f at level 9, only parsing).

Section FrameX.
Variables (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LBX FF LK Aw sp (PMSPA.pm_scr PNVA.VIS_H) spc olo ohi ocell own F fl k LK2 M2 model2 cr (PQMA.aown sa ++ eso).
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar ((PQMA.aown sa ++ eso) ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - 2048 <= spc /\ spc mod 16 = 0.
Local Notation B := (ff_bytes k).
Local Notation FF' := ((F, k, spc + 32) :: FF).
Local Notation GM := (PQAKR3.g_mem L ar HI M model LBX FF LK Aw sp PNVA.VIS_H WA spc own k F).
Local Notation a_mem := (PQAKS3N.a_mem L ar HI M model LBX FF LK Aw cr sp oa ov osk oec sa QE spc own k F).
Local Notation "'SF' f" := (f L ar C IL HI LY HIok ICok ILY K R M model LBX FF LK Aw cr sp r oa ov osk oec sa eso QE HH QENN AM K0 ENT FRM FRS AO O8 AOV APT AOSK AOEC AA OACC AOK VIS BASE spc olo ohi ocell own k F fl LK2 M2 model2 G APART HSPC) (at level 10, f at level 9, only parsing).
Local Notation "'GF' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PNVA.VIS_H (PQMA.aown sa ++ eso) WA HH AM K0 ENT FRM FRS PQAKS3N.Hh3 (SX PQAKS3N.wappW) spc olo ohi ocell own k F fl LK2 M2 model2 G APART HSPC) (at level 10, f at level 9, only parsing).

(* [comment removed for export] *)
Lemma s_xpiece M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (M3 : mem) (Wp : Z -> Prop) kbb1 en1 k1 (b1 e1 : bool) :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> xinv M1 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1 ->
  incl (NEM.enc_own en1) (PQMA.aown st1 ++ eso1) -> incl (NESK.sink_own k1) (PQMA.aown st1 ++ eso1) ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  (forall a, Wp a -> ~ ocell a /\ ((spc <= a < sp) \/ (F <= a < F + B - 8 /\ ~ (F + 24 <= a < F + 32)) \/ (F / 8 + SB <= a < F / 8 + SB + B / 8))) ->
  xinv M3 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1.
Proof using All.
