(* [comment removed for export] *)
Lemma s_xcall (w : bool) M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (M4 : mem) (hc : Z) kbb1 kb4 kbb4 en1 k1 (b1 e1 : bool) :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> xinv M1 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1 ->
  incl (NEM.enc_own en1) eso1 -> incl (NESK.sink_own k1) eso1 -> 0 <= hc ->
  L5CA.ahpres L ar ((s_rest w st1 ++ eso1) ++ LBX) FF' spc (PMSPA.pm_scr hc) [(oa + s_off w, 24)] M1 M4 ->
  (if w then kb4 = PQMA.a_kb st1 /\ kbb4 = kbb1 else NEM.kcontent RSEGS M4 (oa + PQMA.AOFF_KB) kb4 kbb4 /\ utf8_valid kbb4 = true) ->
  xinv M4 kb4 kbb4 en1 k1 b1 e1.
