(* [comment removed for export] *)
Lemma s_xlv M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (M3 : mem) (Wl : list L5.range) kbb1 en1 k1 (b1 e1 : bool) :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> xinv M1 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1 ->
  incl (NEM.enc_own en1) eso1 -> incl (NESK.sink_own k1) eso1 ->
  (forall rr, In rr Wl -> PQMA.a_lb st1 <= fst rr /\ fst rr + snd rr <= PQMA.a_lb st1 + PQMA.LSZ * 2 ^ PQMA.a_lk st1) ->
  (forall a, 0 <= a < 2 ^ 64 -> L5.outside Wl a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  xinv M3 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1.
