(* [comment removed for export] *)
Lemma s_kpiece (w : bool) M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (M3 : mem) (Wp : Z -> Prop) cs :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  (forall a, Wp a -> ~ ocell a /\ ((spc <= a < sp) \/ (F <= a < F + B - 8 /\ ~ (F + 24 <= a < F + 32)) \/ (F / 8 + SB <= a < F / 8 + SB + B / 8))) ->
  NEM.kcontent RSEGS M1 (oa + s_off w) (s_str w st1) cs -> NEM.kcontent RSEGS M3 (oa + s_off w) (s_str w st1) cs.
