Lemma s_kcall (w : bool) M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (M4 : mem) (hc : Z) cs :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> 0 <= hc ->
  L5CA.ahpres L ar ((s_rest w st1 ++ eso1) ++ LBX) FF' spc (PMSPA.pm_scr hc) [(oa + s_off w, 24)] M1 M4 ->
