(* [comment removed for export] *)
Lemma s_xkw M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (M3 : mem) (Wp : Z -> Prop) kbb1 en1 k1 (b1 e1 : bool) :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> xinv M1 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1 ->
  incl (NEM.enc_own en1) eso1 -> incl (NESK.sink_own k1) eso1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  (forall a, Wp a -> (oa + 24 <= a < oa + 48) \/ (exists q m, In (q, m) (PM.vs_own (PQMA.a_key st1)) /\ q <= a < q + m)) ->
  xinv M3 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1.
Proof using All.
