Definition from_argsCQ (v : Z) (df : Z -> Z) (R0 : bvmap 5 word) (M0 : mem) (LB : list (Z * Z)) (FF0 : list fframe) (o SM : Z) (x : PM.vstr) (d : Z) : Prop :=
  getr R0 (reg 10) = Z_to_bv 64 v /\ 0 <= v < 2 ^ 64 /\ getr R0 (reg 11) = Z_to_bv 64 o /\ PM.vs_size x + 20 <= SM /\ PMSTA.base_okA RSEGS AD M0 /\ d = df v.
Lemma from_scCQ pc (df : Z -> Z) v : PQASCA2.from_specCA RSEGS AD L ar HI pc df -> scalleeCQ pc PQASA.FROM_H (from_argsCQ v df) NEM.ascii.
