Section Frame.
Variables (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LBX FF LK Aw sp (PMSPA.pm_scr PNVA.VIS_H) spc olo ohi ocell own F fl k LK2 M2 model2 cr (PQMA.aown sa ++ eso).
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar ((PQMA.aown sa ++ eso) ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - 2048 <= spc /\ spc mod 16 = 0.
Local Notation B := (ff_bytes k).
Local Notation FF' := ((F, k, spc + 32) :: FF).
Local Notation a_mem := (PQAKS3N.a_mem L ar HI M model LBX FF LK Aw cr sp oa ov osk oec sa QE spc own k F).
Local Notation "'SF' f" := (f L ar C IL HI LY HIok ICok ILY K R M model LBX FF LK Aw cr sp r oa ov osk oec sa eso QE HH QENN AM K0 ENT FRM FRS AO O8 AOV APT AOSK AOEC AA OACC AOK VIS BASE spc olo ohi ocell own k F fl LK2 M2 model2 G APART HSPC) (at level 10, f at level 9, only parsing).
Local Notation "'GF' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PNVA.VIS_H (PQMA.aown sa ++ eso) WA HH AM K0 ENT FRM FRS PQAKS3N.Hh3 (SX PQAKS3N.wappW) spc olo ohi ocell own k F fl LK2 M2 model2 G APART HSPC) (at level 10, f at level 9, only parsing).


(* [comment removed for export] *)
Lemma s_call_sCQ (w : bool) M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (fx1 : FPState) R1 (pc ra hc d : Z)
      (args : bvmap 5 word -> mem -> list (Z * Z) -> list fframe -> Z -> Z -> PM.vstr -> Z -> Prop) (post : list Z -> Prop) (bs : list Z) :
  scalleeCQ pc hc args post -> 0 <= hc -> hc + 1 <= PNVA.VIS_H ->
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  args R1 M1 ((s_rest w st1 ++ eso1) ++ LBX) FF' (oa + s_off w) (s_SM w) (s_str w st1) d ->
  NEM.kcontent RSEGS M1 (oa + s_off w) (s_str w st1) bs ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 x' g' cr3 (nb : list Z),
      regs_preserved R1 R2 ->
      a_mem M3 model3 LK3 Aw3 (s_set w st1 x' g') eso1 qe1 cr3 ->
      PM.vs_size x' = PM.vs_size (s_str w st1) + d ->
      NEM.kcontent RSEGS M3 (oa + s_off w) x' (bs ++ nb) -> post nb ->
      L5CA.ahpres L ar ((s_rest w st1 ++ eso1) ++ LBX) FF' spc (PMSPA.pm_scr hc) [(oa + s_off w, 24)] M1 M3 ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc M1 model1) K.
