Module PQAKS3BN.
Import L5A L5SAR PQAKS3N.
Ltac inl := apply L5K.In_of_mem; vm_compute; reflexivity.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := Asan.M.loaded_segments.
Abbreviation mem := (word -> option byte).
Abbreviation AD := PMA.AD.
Abbreviation AQ := PnLayoutQA.QADDR_A.
Abbreviation accA := PMSPA.accA.
Abbreviation annA := PMSPA.annA.
Abbreviation kstr_at := (PQMA.kstr_at RSEGS accA).
Abbreviation lvec_at := (PQMA.lvec_at RSEGS accA annA).
Abbreviation adaptor_at := (PQMA.adaptor_at RSEGS AD accA annA (qa_vp_adaptor AQ)).
Abbreviation bvu x := (bv_unsigned x).

Section Slot.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis ICok : aicpt_ok L ar IL SCFG HI.
Hypothesis ILY : as0_icpt_layout IL.
Let LYa := PMA.ly_as0 L C LY.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r oa ov osk oec : Z) (sa : PQMA.ast) (eso : list (Z * Z)) (QE : credit).
Hypothesis HH : ri_inv HI ((PQMA.aown sa ++ eso) ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis QENN : 0 <= fst QE /\ 0 <= snd QE.   (* [comment removed for export] *)
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r PNVA.VIS_H.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM PNVA.VIS_H FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis AO : PMSPA.aobjA FF oa PQMA.ASIZE.
Hypothesis O8 : oa mod 8 = 0.
Hypothesis AOV : PMSPA.aobjA FF ov 56.
Hypothesis APT : oa + PQMA.ASIZE <= ov \/ ov + 56 <= oa.
Hypothesis AOSK : PMSPA.aobjA FF osk 24.
Hypothesis AOEC : PMSPA.aobjA FF oec 16.
Hypothesis AA : adaptor_at M oa ov sa.
Hypothesis OACC : accA M oa PQMA.ASIZE.
Hypothesis AOK : PQMA.adaptor_ok sa.
Hypothesis VIS : PQAKS3N.EVIS M ov.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Local Notation SCR := (PMSPA.pm_scr PNVA.VIS_H).
Local Notation WA := (NEMA.ae_WA AD oa ov osk oec).
Local Notation AOV8 := (PQAKR3.aobj_sub FF ov 56 ov 8 AOV ltac:(lia) ltac:(lia)).
Local Notation kcontent := (NEM.kcontent RSEGS).
Local Notation POT := (fun x => PMSPA.scA L (PQMA.pot_adaptor (PMSPA.HV L ar) x)).
Local Notation scallee := (PQAKS3N.scallee L ar HI).
Local Notation "'SX' f" := (f L ar C IL HI LY HIok ICok ILY K R M model LBX FF LK Aw cr sp r oa ov osk oec sa eso QE HH QENN AM K0 ENT FRM FRS AO O8 AOV APT AOSK AOEC AA OACC AOK VIS BASE) (at level 10, f at level 9, only parsing).
Local Notation "'GX' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PNVA.VIS_H (PQMA.aown sa ++ eso) WA HH AM K0 ENT FRM FRS PQAKS3N.Hh3 (SX PQAKS3N.wappW)) (at level 10, f at level 9, only parsing).

(* [comment removed for export] *)
Definition scalleeE (pc hc : Z) (args : bvmap 5 word -> mem -> list (Z * Z) -> list fframe -> Z -> Z -> PM.vstr -> Z -> Prop) (P : list Z -> Prop) : Prop :=
  forall (fx : FPState) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K0' : TSet)
         (LB : list (Z * Z)) (FF0 LK0 : list fframe) (Aw0 : list (Z * Z)) (cr0 : credit) (o sp0 r0 SM g d : Z) (x : PM.vstr) (bs : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF0 LK0 cr0 Aw0 M0 (vml_of model0) -> L5CA.amodel_ok Aw0 model0 -> K0' [] ->
    PMSPA.entryA AD L ar R0 M0 sp0 r0 hc -> PGSA.ffroomB PQRA.FCM hc FF0 LK0 -> PMSPA.ffrsA FF0 sp0 -> sp0 mod 16 = 0 ->
    args R0 M0 LB FF0 o SM x d -> PMSPA.aobjA FF0 o 24 -> o mod 8 = 0 -> kstr_at M0 o x -> kcontent M0 o x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) cr0 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit) (nb : list Z),
        regs_preserved R0 R' -> kstr_at M' o x' -> kcontent M' o x' (bs ++ nb) -> P nb -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + d ->
        L5CA.ahpres L ar LB FF0 sp0 (PMSPA.pm_scr hc) [(o, 24)] M0 M' ->
        PMSP.credit_keep cr0 cr' (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x' g')) ->
        model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF0 LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r0 M' model') K0') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R0 pc M0 model0) K0'.

(* [comment removed for export] *)
Definition b64_argsC (q n alph : Z) (R0 : bvmap 5 word) (M0 : mem) (LB : list (Z * Z)) (FF0 : list fframe) (o SM : Z) (x : PM.vstr) (d : Z) : Prop :=
  getr R0 (reg 10) = Z_to_bv 64 q /\ getr R0 (reg 11) = Z_to_bv 64 (q + n) /\ getr R0 (reg 12) = Z_to_bv 64 alph /\ getr R0 (reg 13) = Z_to_bv 64 o
  /\ 0 <= n < 2 ^ 26 /\ PQASA.src_okA RSEGS L HI M0 LB FF0 q n /\ (q + n <= o \/ o + 24 <= q) /\ PM.vs_size x + PQVA.b64len n <= SM
  /\ PMSTA.base_okA RSEGS AD M0 /\ d = PQVA.b64len n.
Lemma b64_scE pc alph q n : PQASCB.b64_specCA RSEGS AD L ar HI pc alph -> scalleeE pc PQASA.B64_H (b64_argsC q n alph) NEM.ascii.
Proof.
