(* [comment removed for export] *)
Lemma s_popX (pcs : Z) M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 lv0 c1 (fx1 fx2 : FPState) R1 R2 (pc1 ra : Z) (M2v : mem) :
  PQSAXR.ann_shrink_lv_spec RSEGS AD L ar HI pcs ->
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> PQMA.a_lv st1 = lv0 ++ [c1] -> (1 <= length lv0)%nat ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pcs M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ (oa + 80 <= a < oa + 88) -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  L5.u64_at RSEGS M2v (oa + 80) (PQMA.a_lb st1 + 24 * Z.of_nat (length lv0)) ->
  getr R2 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R2 (reg 2) = Z_to_bv 64 spc ->
  getr R2 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R2 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R2 (reg 10) = Z_to_bv 64 (oa + 72) -> getr R2 (reg 11) = Z_to_bv 64 (Z.of_nat (length lv0) + 1) ->
  (forall (fx3 : FPState) R3 (M4 : mem) model4 LK4 Aw4,
      regs_preserved R2 R3 -> a_mem M4 model4 LK4 Aw4 (set_lv st1 lv0) eso1 qe1 cr1 ->
      (forall a, spc <= a < sp -> M4 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M4 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (exists M3 : mem, mem_grows M1 M3 /\ L5SAR.ek L ar ((PQMA.aown st1 ++ eso1) ++ LBX) FF sp SCR [(oa + 80, 8)] M1 M3
                        /\ L5CA.ahpres L ar (((PM.vs_own (PQMA.a_key st1) ++ PM.vs_own (PQMA.a_kb st1)) ++ eso1) ++ LBX) FF' spc (PMSPA.pm_scr 0) [] M3 M4) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 ra M4 model4) K) ->
