  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, Wx a -> F / 8 + SB <= a < F / 8 + SB + B / 8) ->
  match PQMA.a_kb st1 with
  | PM.VShort n => (forall i, 0 <= i < 2 ^ 64 -> ~ Wx i -> ~ (oa + 48 <= i < oa + 48 + 2) -> M2v (Z_to_bv 64 i) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 i))
                   /\ L5.u8_at RSEGS M2v (oa + 48) 0
  | PM.VLong c n p => (forall i, 0 <= i < 2 ^ 64 -> ~ Wx i -> ~ (oa + 56 <= i < oa + 56 + 8) -> ~ (p + 0 <= i < p + 0 + 1) -> M2v (Z_to_bv 64 i) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 i))
                      /\ L5.u64_at RSEGS M2v (oa + 56) 0
  end ->
  (forall (M3 : mem) model3,
      a_mem M3 model3 LK1 Aw1 (s_set false st1 (kclr (PQMA.a_kb st1)) (PQMA.a_kbg st1)) eso1 qe1 cr1 ->
      (forall i, 0 <= i < 2 ^ 64 -> ~ Wx i -> ~ (oa + 48 <= i < oa + 72) ->
                 ~ (match PQMA.a_kb st1 with PM.VShort _ => False | PM.VLong _ _ p => p <= i < p + 1 end) -> M3 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
      mem_grows M1 M3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc1 M1 model1) K.
Proof using All.
