Lemma binv_after (HIa HIb : asan_iface) (HIoka : HAJ.asan_iface_okR L ar C SCFG HIa)
      (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (sp oa ov osk oec FR : Z) (own : mem -> Prop) (ocell : Z -> Prop)
      BX BXa BX1 Mc modelc LKc crc Ac M1 model1 LK1 cr1 A1 SCRc (Wc : list L5.range) :
  (forall a, ocell a -> sp - FR <= a < sp) -> (forall M0 M0' : mem, own M0 -> (forall a, ocell a -> M0' (Z_to_bv 64 a) = M0 (Z_to_bv 64 a)) -> own M0') ->
  ahl_ceil ar + 4096 + PMSPA.pm_scr PNVA.VIS_H <= sp -> sp <= 2 ^ 47 -> 0 <= ahl_ceil ar -> 0 <= FR ->
  PQAKSNN.binvN L ar HIa M model LBX FF LK Aw sp oa ov osk oec own BX Mc modelc LKc crc Ac ->
  L5CA.ahpres L ar (BXa ++ LBX) FF (sp - FR) SCRc Wc Mc M1 ->
  ri_inv HIb (BX1 ++ LBX) FF LK1 cr1 A1 M1 (vml_of model1) -> L5CA.amodel_ok A1 model1 -> model_rt modelc model1 -> incl Ac A1 -> incl LK1 LKc ->
  0 <= SCRc -> sp - PMSPA.pm_scr PNVA.VIS_H <= sp - FR - SCRc ->
  (forall rr a, In rr Wc -> L5.in_rng rr a -> ~ (sp - FR <= a < sp)) ->
  (forall a, aclient L ar LBX FF sp (PMSPA.pm_scr PNVA.VIS_H) a -> L5.outside (NEMA.ae_WA AD oa ov osk oec) a -> L5.outside Wc a) ->
  PQAKSNN.binvN L ar HIb M model LBX FF LK Aw sp oa ov osk oec own BX1 M1 model1 LK1 cr1 A1 /\ (forall a, sp - FR <= a < sp -> M1 (Z_to_bv 64 a) = Mc (Z_to_bv 64 a)).
Proof using LY.
