(* [comment removed for export] *)
Lemma enc_keep (HIa : asan_iface) (HIoka : HAJ.asan_iface_okR L ar C SCFG HIa)
      (LBp : list (Z * Z)) (FFc : list fframe) (spc h oa ov osk oec : Z) (st1 : PQMA.ast) (kbb1 : list Z) (en1 : NEM.enc) (k1 : NESK.sink)
      (LK1 : list fframe) (cr1 : credit) (Aw1 : list (Z * Z)) (M1 M4 : mem) (model1 : Model) :
  ri_inv HIa (NECS.eown en1 k1 ++ LBp) FFc LK1 cr1 Aw1 M1 (vml_of model1) ->
  incl (PQMA.aown st1) LBp ->
  PMSPA.aobjA FFc oa 96 -> PMSPA.aobjA FFc ov 56 -> PMSPA.aobjA FFc osk 24 -> PMSPA.aobjA FFc oec 16 ->
  (oa + 96 <= ov \/ ov + 56 <= oa) -> (oa + 96 <= osk \/ osk + 24 <= oa) -> (oa + 96 <= oec \/ oec + 16 <= oa) ->
  7036928 <= oa -> oa + 96 <= 2 ^ 47 ->
  (2147446784 + 17592186048512 <= ov \/ ov + 56 <= 2147446784) -> (2147446784 + 17592186048512 <= osk \/ osk + 24 <= 2147446784) ->
  (2147446784 + 17592186048512 <= oec \/ oec + 16 <= 2147446784) ->
  adaptor_at M1 oa ov st1 -> accA M1 oa PQMA.ASIZE -> NEM.kcontent RSEGS M1 (oa + PQMA.AOFF_KB) (PQMA.a_kb st1) kbb1 ->
  L5CA.ahpres L ar LBp FFc spc (PMSPA.pm_scr h) (NECS.W_enc AD ov osk oec) M1 M4 ->
