Hypothesis ICok : aicpt_ok L ar IL SCFG (HIk D).
(* [comment removed for export] *)
Hypothesis TSNN : forall t q Dx RCx, 0 <= fst (tspE t q Dx RCx) /\ 0 <= snd (tspE t q Dx RCx).
Local Notation HI := (HIk D).
Local Notation HIok := (HAR.fr_base L ar C SCFG LR HIk FAMok D).
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (sp r oa ov osk oec : Z) (sa : PQMA.ast) (eso : list (Z * Z)) (QE : credit).
Hypothesis HH : ri_inv HI ((PQMA.aown sa ++ eso) ++ LBX) FF LK cr Aw M (vml_of model).
Hypothesis QENN : 0 <= fst QE /\ 0 <= snd QE.
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSPA.entryA AD L ar R M sp r PNVA.VIS_H.
Hypothesis FRM : PGSA.ffroomB PQRA.FCM PNVA.VIS_H FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis AO : PMSPA.aobjA FF oa PQMA.ASIZE.
Hypothesis O8 : oa mod 8 = 0.
Hypothesis AOV : PMSPA.aobjA FF ov 56.
Hypothesis APT : oa + PQMA.ASIZE <= ov \/ ov + 56 <= oa.
Hypothesis AOSK : PMSPA.aobjA FF osk 24.
Hypothesis AOEC : PMSPA.aobjA FF oec 16.
Hypothesis AA : adaptor_at M oa ov sa.
Hypothesis OACC : accA M oa PQMA.ASIZE.
Hypothesis AOK : PQMA.adaptor_ok sa.
Hypothesis VIS : EVIS M ov.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis CR : PMSP.credit_le (PM.credit_add (PMSPA.scA L (PQMA.pot_adaptor (PMSPA.HV L ar) sa)) QE) cr.
Variables (FR : Z) (ocell : Z -> Prop) (own : mem -> Prop).
Hypothesis HFR : 16 <= FR <= 2048 /\ FR mod 16 = 0.
Hypothesis GOCR : forall a, ocell a -> sp - FR <= a < sp.
Hypothesis GOWN : forall M1 M1' : mem, own M1 -> (forall a, ocell a -> M1' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> own M1'.
Variable cat : Z.
Hypothesis OV8 : ov mod 8 = 0.
Hypothesis OK8 : osk mod 8 = 0.
Hypothesis OE8 : oec mod 8 = 0.
Hypothesis APT2 : oa + PQMA.ASIZE <= osk \/ osk + 24 <= oa.
Hypothesis APT3 : oa + PQMA.ASIZE <= oec \/ oec + 16 <= oa.
Hypothesis APT4 : ov + 56 <= osk \/ osk + 24 <= ov.
Hypothesis APT5 : oec + 16 <= ov \/ ov + 56 <= oec.
Hypothesis APT6 : oec + 16 <= osk \/ osk + 24 <= oec.
Local Notation spc := (sp - FR).
Local Notation SCR := (PMSPA.pm_scr PNVA.VIS_H).
Local Notation WA := (NEMA.ae_WA AD oa ov osk oec).
(* [comment removed for export] *)
Local Notation n_memF Dx := (PQAKSNN.n_memG L ar (HIk Dx) M model LBX FF LK Aw cr sp oa ov osk oec sa QE own).
Local Notation xinv := (PQAKENA.xinvG L ar oa ov osk oec cat).
Local Notation "'SN' f" := (f L ar C IL HI LY HIok ICok ILY K R M model LBX FF LK Aw cr sp r oa ov osk oec sa eso QE HH QENN AM K0 ENT FRM FRS AO O8 AOV APT AOSK AOEC AA OACC AOK VIS BASE CR FR ocell own HFR GOCR GOWN) (at level 10, f at level 9, only parsing).

Lemma ENC_SLOTF (pc h : Z)
      (args : NECS.eargs -> list fframe -> bvmap 5 word -> mem -> Z -> Z -> Z -> list (Z * Z) -> Prop)
      (pre : NECS.eargs -> NEM.enc -> NESK.sink -> Prop)
      (step : NECS.eargs -> NEM.enc -> NESK.sink -> bool -> NEM.enc -> NESK.sink -> bool -> Prop)
      (a : NECS.eargs) M1 model1 LK1 Aw1 st1 cr1 kbb1 en1 k1 (b1 e1 : bool) (fx1 : FPState) R1 (ra : Z) (RC : list Z) :
  NECSA.eslot_specF RSEGS AD AQ AAD AE L ar HIk (NESKA.PMEA L) tspE pc h args pre step -> 0 <= h -> h + 1 <= PNVA.VIS_H ->
  n_memF D M1 model1 LK1 Aw1 st1 (NECS.eown en1 k1) (PM.credit_add (EPOT en1 k1) (tspE (NECS.ea_tag a) ra D RC)) cr1 ->
  xinv M1 (PQMA.a_kb st1) kbb1 en1 k1 b1 e1 ->
  HAR.rchain L ar M1 spc (bv_unsigned (getr R1 8%bv)) RC -> bv_unsigned (getr R1 8%bv) <> spc + 8 ->   (* [comment removed for export] *)
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 ov ->
  args a FF R1 M1 osk ov oec (PQMA.aown st1 ++ LBX) ->
  pre a en1 k1 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 Aw4 en4 k4 (b4 e4 : bool) cr4 (D4 : list (list Z)),
      regs_preserved R1 R4 -> incl D D4 ->
      n_memF D4 M4 model4 LK4 Aw4 st1 (NECS.eown en4 k4) (PM.credit_add (EPOT en4 k4) (tspE (NECS.ea_tag a) ra D4 RC)) cr4 ->
      xinv M4 (PQMA.a_kb st1) kbb1 en4 k4 b4 e4 ->
      (b1 = true -> b4 = true) -> (e1 = true -> e4 = true) -> step a en1 k1 b1 en4 k4 b4 ->
      (forall c, spc <= c < sp -> M4 (Z_to_bv 64 c) = M1 (Z_to_bv 64 c)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc M1 model1) K.
Proof using All.
